    wait for 1 ns;
    assert output_bit = '1' report "zero case failed" severity failure;
    input_bit <= '1';
    wait for 1 ns;
    assert output_bit = '0' report "one case failed" severity failure;
    report "two cases passed" severity note;
    wait;
  end process;
end test;

